/**
 * Drive 语熙 from a WAV file.
 *
 *   node examples/drive-wav.js path\to\audio.wav path\to\out
 */
import path from "node:path";
import { fileURLToPath } from "node:url";
import { Duix } from "../src/index.js";

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, "..", "..", "..");

const wav = process.argv[2];
const outDir = process.argv[3] || path.join(root, "js", "duix-sdk", "out");
if (!wav) {
  console.error("usage: node examples/drive-wav.js <audio.wav> [outDir]");
  process.exit(1);
}

const duix = new Duix({
  baseDir: path.join(root, "client", "resource", "gj_dh_res"),
  roleDir: path.join(root, "output", "语熙"),
});

const info = await duix.init();
console.log("ready", info);
const n = await duix.driveWav(wav, {
  outDir,
  onFrame: ({ index, total }) => {
    if (index % 25 === 0) console.log(`frame ${index}/${total}`);
  },
});
duix.close();
console.log(`wrote ${n} frames to ${outDir}`);
